.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
d<-read.csv('outputs/stage6_rbm6_gnomad_aligned.csv');p<-nrow(d);readR<-function(pop){R<-matrix(readBin(paste0('work/stage6_rbm6_gnomad_',pop,'_ld.bin'),'double',n=p*p,size=8,endian='little'),p,p);dimnames(R)<-list(d$rs,d$rs);stopifnot(min(eigen(R,symmetric=TRUE,only.values=TRUE)$values)> -1e-8);R};Rn<-readR('nfe');Rf<-readR('fin');traits<-c('Jansen_insomnia','FinnGen_HFRS','Mak_FI','Ye_FFS');ns<-c(313750,500737,402910,386565);fits<-list();diag<-list();members<-list();for(i in seq_along(traits)){t<-traits[i];z<-d[[paste0(t,'_beta_alt')]]/d[[paste0(t,'_se')]];names(z)<-d$rs;R<-if(t=='FinnGen_HFRS')Rf else Rn;lambda<-estimate_s_rss(z,R,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=R,n=ns[i],L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[t]]<-f;diag[[i]]<-data.frame(trait=t,reference=if(t=='FinnGen_HFRS')'FIN' else 'NFE',working_n=ns[i],n_variants=p,lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip));if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){idx<-f$sets$cs[[k]];members[[length(members)+1]]<-data.frame(trait=t,component=f$sets$cs_index[k],rs=d$rs[idx],pip=f$pip[idx])};cat(t,'sets',length(f$sets$cs),'lambda',lambda,'converged',f$converged,'\n');flush.console()};write.csv(do.call(rbind,diag),'outputs/stage6_rbm6_gnomad_susie_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_rbm6_gnomad_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_rbm6_gnomad_susie_fits.rds');out<-list();a<-fits[['Jansen_insomnia']];for(t in traits[-1]){b<-fits[[t]];if(!a$converged||!b$converged||!length(a$sets$cs)||!length(b$sets$cs))next;for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(a,b,p1=1e-4,p2=1e-4,p12=p12)$summary);x$trait1<-'Jansen_insomnia';x$trait2<-t;x$p12<-p12;out[[length(out)+1]]<-x}};if(length(out))write.csv(do.call(rbind,out),'outputs/stage6_rbm6_gnomad_susie_coloc.csv',row.names=FALSE)
